            else:
                lines_after_imports = 1

            blank_lines = [""] * lines_after_imports
            overflow_form_feeds = ""
            for index, line in enumerate(trailing_blank_lines):
                form_feeds = "".join(character for character in line if character == "\f")
                if index < lines_after_imports:
