def _parse_angle_link_href(src: str, pos: int) -> Union[Tuple[str, int], Tuple[None, None]]:
    start = pos + 1
    pos = start
    while pos < len(src):
        c = src[pos]
        if c == ">":
            return src[start:pos], pos + 1
        if c == "\\":
            pos = min(pos + 2, len(src))
            continue
        if c in "<\n\r\x00":
            return None, None
        pos += 1
    return None, None

