def _date_diff_sql(self: PostgresGenerator, expression: exp.DateDiff | exp.TsOrDsDiff) -> str:
    unit = expression.text("unit").upper() or "DAY"

    # Dialects like MySQL count crossed day boundaries, which maps to DATE subtraction
    if unit == "DAY" and expression.args.get("date_part_boundary"):
        this = exp.cast(expression.this, exp.DType.DATE)
        expr = exp.cast(expression.expression, exp.DType.DATE)
        return self.sql(exp.paren(this - expr))

    factor = DATE_DIFF_FACTOR.get(unit)

    end = f"CAST({self.sql(expression, 'this')} AS TIMESTAMP)"
    start = f"CAST({self.sql(expression, 'expression')} AS TIMESTAMP)"

    # The arithmetic below counts complete units between the operands, whereas dialects that set
    # date_part_boundary count unit boundary crossings, so the operands are truncated down to the
    # unit to make the two coincide. WEEK is left out: its start day differs across dialects
    if expression.args.get("date_part_boundary") and unit in DATE_DIFF_BOUNDARY_UNITS:
        end = self.func("DATE_TRUNC", exp.Literal.string(unit), end)
        start = self.func("DATE_TRUNC", exp.Literal.string(unit), start)

    if factor is not None:
        return f"CAST(EXTRACT(epoch FROM {end} - {start}){factor} AS BIGINT)"

    age = f"AGE({end}, {start})"

    if unit == "WEEK":
        unit = f"EXTRACT(days FROM ({end} - {start})) / 7"
    elif unit == "MONTH":
        unit = f"EXTRACT(year FROM {age}) * 12 + EXTRACT(month FROM {age})"
    elif unit == "QUARTER":
        unit = f"EXTRACT(year FROM {age}) * 4 + EXTRACT(month FROM {age}) / 3"
    elif unit == "YEAR":
        unit = f"EXTRACT(year FROM {age})"
    else:
        unit = age

    return f"CAST({unit} AS BIGINT)"

