            else:
                node = exp.JSONPathSubscript(this=indexes[0])
        else:
            node = exp.JSONPathUnion(expressions=indexes)
    else:
        raise ParseError(_error("Cannot have empty segment"))

    _match(TokenType.R_BRACKET, raise_unmatched=True)

    return node

